// page/view.js
var LAB_NAMES = Object.freeze({
  anthropic: "Anthropic",
  openai: "OpenAI",
  google: "Google",
  deepseek: "DeepSeek",
  moonshot: "Moonshot",
  moonshotai: "Moonshot",
  zhipu: "Zhipu",
  zhipuai: "Zhipu",
  alibaba: "Alibaba",
  qwen: "Alibaba",
  minimax: "MiniMax",
  xai: "xAI",
  mistral: "Mistral",
  meta: "Meta",
  stepfun: "StepFun"
});
var normalize = (value) => String(value ?? "").normalize("NFKC").toLocaleLowerCase();
function labFor(model) {
  const prefix = String(model?.id ?? "").split("/")[0];
  return LAB_NAMES[prefix.toLocaleLowerCase()] ?? prefix;
}
